Rules.InvariantScript:
Refresh('Articoli-BC');
Set(varArticoloSel, LookUp('Articoli-BC', Nr = ThisItem.Nr));
Set(varPopupArticolo, true);
Set(varQtaSel, 1);
Set(varMenuAperto,false)

If(
    IsBlank(txtQtaRiordino.Text) || Value(txtQtaRiordino.Text) <= 0,
    Notify("Inserisci una quantità valida", NotificationType.Error),
    IsBlank(cmbMotivoRiordino.Selected.Value),
    Notify("Seleziona una motivazione", NotificationType.Error),
    // tutto ok, procedi
    Set(
        varRiordinoCreato,
        Patch(
            'Riordini-BC',
            Defaults('Riordini-BC'),
            {
                Title: varArticoloSel.Nr,
                CodArticolo: varArticoloSel.Nr,
                Descrizione: varArticoloSel.Descrizione,
                QtaRichiesta: Value(txtQtaRiordino.Text),
                Motivazione: { Value: cmbMotivoRiordino.Selected.Value },
                Note: txtNotaRiordino.Text,
                Stato: { Value: If(varRuoloUtente = "Manager", "Approvato", "InAttesa") },
                Richiedente: Left(varUtenteCorrente.Email, Find("@", varUtenteCorrente.Email) - 1),
                DataRichiesta: Today()
            }
        )
    );
    If(
        varRuoloUtente = "Manager",
        Patch(
            'Articoli-BC',
            LookUp('Articoli-BC', Nr = varArticoloSel.Nr),
            { 'Quantità residua': Value(varArticoloSel.'Quantità residua') + Value(txtQtaRiordino.Text) }
        ),
        Patch(
            'Notifiche-BC',
            Defaults('Notifiche-BC'),
            {
                Title: "Richiesta riordino: " & varArticoloSel.Descrizione,
                TipoNotifica: { Value: "RichiestaRiordino" },
                Mittente: Left(varUtenteCorrente.Email, Find("@", varUtenteCorrente.Email) - 1),
                Destinatario: "Manager",
                Messaggio: "Richiesti " & txtQtaRiordino.Text & " pz di " & varArticoloSel.Descrizione & " (Cod. " & varArticoloSel.Nr & ") — " & cmbMotivoRiordino.Selected.Value,
                Letta: false,
                Data: Now(),
                LinkRif: Text(varRiordinoCreato.ID)
            }
        )
    );
    Notify(If(varRuoloUtente = "Manager", "Riordino registrato: +" & txtQtaRiordino.Text & " pz", "Richiesta inviata al Manager"), NotificationType.Success);
    Reset(txtQtaRiordino);
    Reset(cmbMotivoRiordino);
    Reset(txtNotaRiordino);
    Set(varPopupRiordino, false)
)

ControlPropertyState.AutoRuleBindingString:
Patch(
    'Riordini-BC',
    Defaults('Riordini-BC'),
    {
        Titolo: varArticoloSel.Nr,
        CodArticolo: varArticoloSel.Nr,
        Descrizione: varArticoloSel.Descrizione,
        QtaRichiesta: Value(txtQtaRiordino.Text),
        Motivazione: txtMotivoRiordino.Text,
        Stato: { Value: "Approvato" },
        Richiedente: Left(varUtenteCorrente.Email, Find("@", varUtenteCorrente.Email) - 1),
        DataRichiesta: Today()
    }
);
Patch(
    'Articoli-BC',
    LookUp('Articoli-BC', Nr = varArticoloSel.Nr),
    { 'Quantità residua': Value(varArticoloSel.'Quantità residua') + Value(txtQtaRiordino.Text) }
);
Notify("Riordino registrato: +" & txtQtaRiordino.Text & " pz", NotificationType.Success);
Reset(txtQtaRiordino);
Reset(txtMotivoRiordino);
Set(varPopupRiordino, false)

Rules.InvariantScript:
Patch(
    'MovimentoArticoli-BC',
    Defaults('MovimentoArticoli-BC'),
    {
        'Nr articolo': Value(ThisItem.NrArt),
        'Quantità residua': Value(ThisItem.Qta) // Rimette la quantità positiva nel database
    }
);
Remove(colRigheOrdine, ThisItem)

With(
    { qtaInserita: Value(TextInput4.Text) },
    With(
        { qtaMax: Value(LookUp('Articoli-BC', Value(Nr) = ThisItem.NrArt).'Quantità residua') },
        If(
            qtaInserita > qtaMax,
            UpdateIf(colRigheOrdine, NrArt = ThisItem.NrArt, { Qta: qtaMax });
            Notify("Quantità massima disponibile: " & qtaMax, NotificationType.Warning),
            UpdateIf(colRigheOrdine, NrArt = ThisItem.NrArt, { Qta: qtaInserita })
        )
    )
)

If(
    CountRows(colRigheOrdine) = 0,
    Notify("Il carrello è vuoto. Aggiungi almeno un articolo.", NotificationType.Error),

    !IsBlank(
        First(
            Filter(
                colRigheOrdine,
                !LookUp('Articoli-BC', Value(Nr) = NrArt).Disponibile
            )
        )
    ),
    Notify(
        "Il prodotto """ &
        First(
            Filter(
                colRigheOrdine,
                !LookUp('Articoli-BC', Value(Nr) = NrArt).Disponibile
            )
        ).Descrizione &
        """ non è più disponibile. Rimuovilo dal carrello per procedere.",
        NotificationType.Error
    ),

    Set(varNuovoNr, Max('Ordini-BC', Value(Nr)) + 1);
    Patch(
        'Ordini-BC',
        Defaults('Ordini-BC'),
        {
            'Tipo di documento': "Ordine",
            Nr: Text(varNuovoNr),
            'Fatturare a - Nome': varClienteOrdine.Nome,
            'Fatturare a - Città': varClienteOrdine.Città,
            'Data ordine': Today(),
            Stato: "Aperto",
            'ID-Cliente': varClienteOrdine.ID
        }
    );
    ForAll(
        colRigheOrdine As R,
        Patch(
            'RigheOrdini-BC',
            Defaults('RigheOrdini-BC'),
            {
                'Tipo di documento': "Ordine",
                'Nr documento': Text(varNuovoNr),
                'Nr riga': (CountRows(Filter(colRigheOrdine, NrArt <= R.NrArt))) * 10000,
                Tipo: "Articolo",
                Nr: Text(R.NrArt),
                Descrizione: R.Descrizione,
                Quantità: R.Qta,
                'Prezzo unitario': R.Prezzo,
                Importo: R.Qta * R.Prezzo
            }
        )
    );
    ForAll(
        colRigheOrdine As R,
        UpdateIf(
            'Articoli-BC',
            Value(Nr) = R.NrArt,
            { 'Quantità residua': Value('Quantità residua') - R.Qta }
        )
    );

    ForAll(
        colRigheOrdine As R,
        Patch(
            'MovimentoArticoli-BC',
            Defaults('MovimentoArticoli-BC'),
            {
                'Nr articolo': R.NrArt,
                'Quantità residua': R.Qta * -1
            }
        )
    );
    Refresh('Articoli-BC');
    If(
        !IsBlank(varArticoloSel),
        Set(varArticoloSel, LookUp('Articoli-BC', Value(Nr) = Value(varArticoloSel.Nr)))
    );

    Notify("Ordine " & varNuovoNr & " creato con successo! ✔", NotificationType.Success);
    Clear(colRigheOrdine);
    Set(varOrdineAttivo, false);
    Set(varClienteOrdine, Blank());
    Set(varPopupCarrello, false);

    Navigate(scrCustomers, ScreenTransition.Fade)
)

With(
    { articoloAggiornato: LookUp('Articoli-BC', Nr = varArticoloSel.Nr) },
    If(
        !articoloAggiornato.Disponibile,
        Notify("Questo prodotto è stato disattivato nel frattempo. Impossibile procedere.", NotificationType.Error),

        If(
            varOrdineAttivo,

            // --- IL TUO CORE INTATTO ---
            If(
                IsBlank(LookUp(colRigheOrdine, NrArt = Value(varArticoloSel.Nr))),
                Collect(colRigheOrdine, {
                    NrArt: Value(varArticoloSel.Nr),
                    Descrizione: varArticoloSel.Descrizione,
                    Prezzo: Value(varArticoloSel.'Prezzo unitario'),
                    Qta: varQtaSel
                }),
                UpdateIf(colRigheOrdine, NrArt = Value(varArticoloSel.Nr), { Qta: Qta + varQtaSel })
            );
            // --- FINE CORE ---

            Notify(varArticoloSel.Descrizione & " ×" & varQtaSel & " aggiunto all'ordine", NotificationType.Success);
            Set(varPopupArticolo, false),

            // --- SE SEI DAI PRODOTTI SENZA CLIENTE (varOrdineAttivo = false) ---
            Notify("⚠ Non puoi ordinare senza selezionare un cliente. Vai su Customers e crea un nuovo ordine.", NotificationType.Warning)
        )
    )
)

ControlPropertyState.AutoRuleBindingString:
If(
    varOrdineAttivo,
    If(
        IsBlank(LookUp(colRigheOrdine, NrArt = Value(varArticoloSel.Nr))),
        Collect(colRigheOrdine, {
            NrArt: Value(varArticoloSel.Nr),
            Descrizione: varArticoloSel.Descrizione,
            Prezzo: Value(varArticoloSel.'Prezzo unitario'),
            Qta: varQtaSel
        }),
        UpdateIf(colRigheOrdine, NrArt = Value(varArticoloSel.Nr), { Qta: Qta + varQtaSel })
    );
    Notify(varArticoloSel.Descrizione & " ×" & varQtaSel & " aggiunto all''ordine", NotificationType.Success);
    Set(varPopupArticolo, false),
    Notify("⚠ Non puoi ordinare senza selezionare un cliente. Vai su Customers e crea un nuovo ordine.", NotificationType.Warning)
)

Rules.InvariantScript:
Navigate(scrProducts, ScreenTransition.Fade);
Set(varOrdineAttivo, false);
Set(varClienteOrdine, Blank());
Clear(colRigheOrdine);
Navigate(scrProducts)
